import socket

def portas_abertas(host, inicio, fim):
    abertas = []
    for porta in range(inicio, fim):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        if s.connect_ex((host, porta)) == 0:
            abertas.append(porta)
        s.close()
    return abertas

print(portas_abertas("10.0.0.5", 20, 25))
